    INSERT INTO public.locations (name, country, country_code, type, latitude, longitude, summary, featured) VALUES
    ('Lahore', 'Pakistan', 'PK', 'city'::public.location_type, 31.5204, 74.3587, 'A dense historic city on the Punjab plain where winter smog, vehicle and industrial emissions, and regional crop residue burning combine into one of the world''s most persistent urban air quality crises.', true),
    ('Karachi', 'Pakistan', 'PK', 'city'::public.location_type, 24.8607, 67.0011, 'Pakistan''s largest coastal megacity, facing severe summer heat, chronic water supply stress, and heavily strained solid waste and drainage systems.', false),
    ('Jakarta', 'Indonesia', 'ID', 'city'::public.location_type, -6.2088, 106.8456, 'A low-lying coastal capital affected by land subsidence from groundwater extraction, tidal and river flooding, and dense urban air pollution.', true),
    ('Cape Town', 'South Africa', 'ZA', 'city'::public.location_type, -33.9249, 18.4241, 'A Mediterranean-climate city that came close to running out of municipal water during the 2015-2018 drought, and now plans around long-term supply variability.', true),
    ('Dubai', 'United Arab Emirates', 'AE', 'city'::public.location_type, 25.2048, 55.2708, 'A desert city built on desalinated water and energy-intensive cooling, now investing heavily in solar generation while managing extreme heat and dust.', true),
    ('Miami', 'United States', 'US', 'city'::public.location_type, 25.7617, -80.1918, 'A low-elevation coastal city on porous limestone, exposed to sea level rise, tidal flooding, hurricanes and saltwater intrusion into freshwater supplies.', true),
    ('Manaus / Amazon', 'Brazil', 'BR', 'region'::public.location_type, -3.119, -60.0217, 'The largest city of the Brazilian Amazon and gateway to the rainforest basin, where deforestation, fire and extreme river droughts intersect.', true),
    ('Singapore', 'Singapore', 'SG', 'city'::public.location_type, 1.3521, 103.8198, 'A dense island city-state with limited land and no natural freshwater reserves, addressing water security, waste land scarcity and urban heat through planning and technology.', true),
    ('Delhi', 'India', 'IN', 'city'::public.location_type, 28.6139, 77.209, 'A vast northern Indian capital region where winter air pollution, water stress and extreme heat affect tens of millions of people.', false),
    ('Rotterdam', 'Netherlands', 'NL', 'city'::public.location_type, 51.9244, 4.4777, 'A major European port city largely below sea level, internationally known for delta engineering, climate adaptation and port decarbonisation.', true),
    ('Northern Pakistan / Gilgit-Baltistan', 'Pakistan', 'PK', 'region'::public.location_type, 35.9208, 74.3144, 'A high-mountain region where the Karakoram, Himalaya and Hindu Kush meet, holding some of the largest glacier systems outside the polar regions and feeding the Indus river.', false),
    ('Mumbai', 'India', 'IN', 'city'::public.location_type, 19.076, 72.8777, 'A coastal megacity built largely on reclaimed land between former islands, exposed to intense monsoon rainfall, coastal flooding and pressure on its remaining mangroves.', false),
    ('Bengaluru', 'India', 'IN', 'city'::public.location_type, 12.9716, 77.5946, 'A fast-growing technology hub on the Deccan plateau, far from any large river, where lake loss, groundwater dependence and urban flooding reflect rapid unplanned growth.', false),
    ('Beijing', 'China', 'CN', 'city'::public.location_type, 39.9042, 116.4074, 'China''s capital, once synonymous with severe winter smog, now an often-cited case of large-scale air pollution control, while still facing water scarcity on the North China Plain.', false),
    ('Shanghai', 'China', 'CN', 'city'::public.location_type, 31.2304, 121.4737, 'A low-lying megacity on the Yangtze River delta, managing historical land subsidence, typhoon and storm surge exposure, and sea level rise.', false),
    ('Dhaka', 'Bangladesh', 'BD', 'city'::public.location_type, 23.8103, 90.4125, 'One of the world''s densest megacities, where brick kiln and traffic emissions, polluted rivers and monsoon waterlogging shape daily life.', false),
    ('Coastal Bangladesh / Khulna', 'Bangladesh', 'BD', 'region'::public.location_type, 22.8456, 89.5403, 'The low-lying southwest delta around Khulna and the Sundarbans mangrove forest, facing cyclones, storm surges and increasing salinity in soil and water.', false),
    ('Kalimantan / Indonesian Borneo', 'Indonesia', 'ID', 'region'::public.location_type, -1.68, 113.38, 'The Indonesian part of Borneo, home to tropical rainforest and vast carbon-rich peatlands under pressure from plantations, mining, drainage and fire.', false),
    ('Manila', 'Philippines', 'PH', 'city'::public.location_type, 14.5995, 120.9842, 'The dense capital region on Manila Bay, exposed to typhoons and flooding, and a focus of research on river-borne plastic pollution.', false),
    ('Palawan', 'Philippines', 'PH', 'region'::public.location_type, 9.8349, 118.7384, 'A long island province often described as one of the Philippines'' last ecological frontiers, with extensive forests, mangroves and coral reefs.', false),
    ('Tokyo', 'Japan', 'JP', 'city'::public.location_type, 35.6762, 139.6503, 'The world''s largest metropolitan area, managing intense summer urban heat and river flood risk with large engineered infrastructure and city-level climate policy.', false),
    ('Nairobi', 'Kenya', 'KE', 'city'::public.location_type, -1.2921, 36.8219, 'East Africa''s major hub and host city of the UN Environment Programme, facing river pollution, waste management and air quality challenges alongside rapid growth.', false),
    ('Northern Kenya', 'Kenya', 'KE', 'region'::public.location_type, 2.9, 37.3, 'Arid and semi-arid lands around Marsabit, Turkana and Lake Turkana, where pastoralist communities are highly exposed to recurring drought.', false),
    ('Lagos', 'Nigeria', 'NG', 'city'::public.location_type, 6.5244, 3.3792, 'Africa''s largest urban agglomeration by many estimates, built around a lagoon system on a low coastline exposed to flooding, erosion and waste pressure.', false),
    ('Niger Delta', 'Nigeria', 'NG', 'region'::public.location_type, 4.9, 6.4, 'One of the world''s largest wetlands and the centre of Nigeria''s oil industry, where decades of oil spills and gas flaring have damaged ecosystems and livelihoods.', false),
    ('Bogotá', 'Colombia', 'CO', 'city'::public.location_type, 4.711, -74.0721, 'A high-altitude Andean capital that depends on páramo ecosystems for water, and is known for bus rapid transit and cycling policy.', false),
    ('Colombian Amazon', 'Colombia', 'CO', 'region'::public.location_type, 0.8, -72.7, 'The Amazonian departments of southern Colombia, including Chiribiquete National Park, where the forest frontier is under pressure from land grabbing and cattle ranching.', false),
    ('Mexico City', 'Mexico', 'MX', 'city'::public.location_type, 19.4326, -99.1332, 'A megacity built on a former lake bed in a high mountain basin, facing severe land subsidence, water supply stress and ozone pollution.', false),
    ('Los Angeles', 'United States', 'US', 'city'::public.location_type, 34.0522, -118.2437, 'A sprawling Southern California region with a long history of smog control, exposed to wildfire, drought and dependence on imported water.', false),
    ('Phoenix', 'United States', 'US', 'city'::public.location_type, 33.4484, -112.074, 'A fast-growing desert metropolis in the Sonoran Desert, facing dangerous extreme heat and long-term uncertainty over Colorado River supply.', false),
    ('Western Canada', 'Canada', 'CA', 'region'::public.location_type, 52.5, -121.5, 'British Columbia and Alberta, where forests, mountains and communities have experienced record heat and increasingly severe wildfire seasons.', false),
    ('Arctic Canada', 'Canada', 'CA', 'region'::public.location_type, 69.5, -95, 'Canada''s northern territories, warming faster than the country as a whole, where permafrost thaw and sea ice change affect Inuit communities and infrastructure.', false),
    ('Sydney', 'Australia', 'AU', 'city'::public.location_type, -33.8688, 151.2093, 'Australia''s largest city, framed by national parks and exposed to bushfire smoke, heatwaves and a pronounced heat gap between its coastal and western suburbs.', false),
    ('Great Barrier Reef', 'Australia', 'AU', 'region'::public.location_type, -18.2871, 147.6992, 'The world''s largest coral reef system, a UNESCO World Heritage Area repeatedly affected by marine heatwaves and mass coral bleaching.', true),
    ('London', 'United Kingdom', 'GB', 'city'::public.location_type, 51.5074, -0.1278, 'A tidal-river capital that pioneered clean air law after the 1952 smog, now managing traffic pollution and long-term Thames flood risk.', false),
    ('Berlin', 'Germany', 'DE', 'city'::public.location_type, 52.52, 13.405, 'A green, relatively flat capital adapting to hotter, drier summers and heavy rainfall through its ''sponge city'' approach to rainwater.', false),
    ('Southern France', 'France', 'FR', 'region'::public.location_type, 43.7, 5, 'The Mediterranean south of France, including Provence and Occitanie, increasingly affected by heatwaves, drought and wildfire risk.', false),
    ('Madagascar', 'Madagascar', 'MG', 'country'::public.location_type, -18.7669, 46.8691, 'A large island nation with exceptionally high levels of endemic species, where forest loss and recurring drought in the south affect both biodiversity and people.', false),
    ('Arctic', 'International', 'INTL', 'global'::public.location_type, 80, -20, 'The region around the North Pole, warming several times faster than the global average, with declining sea ice and consequences that reach far beyond the polar north.', false),
    ('Copenhagen', 'Denmark', 'DK', 'city'::public.location_type, 55.6761, 12.5683, 'Denmark''s capital, internationally referenced for cycling infrastructure, district heating and a citywide cloudburst adaptation plan.', true),
    ('Pakistan', 'Pakistan', 'PK', 'country'::public.location_type, 30.3753, 69.3451, 'A country stretching from the Arabian Sea to some of the world''s highest mountains, highly exposed to heat, flooding and air pollution, and dependent on the Indus river system.', false),
    ('India', 'India', 'IN', 'country'::public.location_type, 20.5937, 78.9629, 'The world''s most populous country, where air quality, groundwater, heat and monsoon variability are central environmental concerns.', false),
    ('China', 'China', 'CN', 'country'::public.location_type, 35.8617, 104.1954, 'The world''s largest energy consumer and emitter of greenhouse gases, and also the largest builder of renewable energy capacity, with major air and water pollution programmes.', false),
    ('Bangladesh', 'Bangladesh', 'BD', 'country'::public.location_type, 23.685, 90.3563, 'A densely populated, low-lying delta nation that is among the most exposed in the world to flooding, cyclones and sea level rise.', false),
    ('Indonesia', 'Indonesia', 'ID', 'country'::public.location_type, -0.7893, 113.9213, 'The world''s largest archipelagic nation, holding extensive tropical forests, peatlands and coral reefs, with a rapidly growing urban population.', false),
    ('Philippines', 'Philippines', 'PH', 'country'::public.location_type, 12.8797, 121.774, 'An archipelago in the western Pacific typhoon belt, rich in marine biodiversity and facing plastic pollution, flooding and coastal hazards.', false),
    ('Japan', 'Japan', 'JP', 'country'::public.location_type, 36.2048, 138.2529, 'A mountainous island nation exposed to typhoons, heavy rainfall and heat, with long experience in disaster risk reduction.', false),
    ('United Arab Emirates', 'United Arab Emirates', 'AE', 'country'::public.location_type, 23.4241, 53.8478, 'A hyper-arid Gulf state relying on desalination for drinking water, with very high cooling demand and growing investment in solar energy.', false),
    ('Kenya', 'Kenya', 'KE', 'country'::public.location_type, -0.0236, 37.9062, 'An East African country with a largely renewable electricity grid, extensive arid lands vulnerable to drought, and globally important wildlife ecosystems.', false),
    ('South Africa', 'South Africa', 'ZA', 'country'::public.location_type, -30.5595, 22.9375, 'A water-scarce country with a coal-dominated power system and exceptional biodiversity, including the Cape Floristic Region.', false),
    ('Nigeria', 'Nigeria', 'NG', 'country'::public.location_type, 9.082, 8.6753, 'Africa''s most populous country, facing oil pollution in the Niger Delta, rapid urbanisation, flooding and desertification pressures in the north.', false),
    ('Brazil', 'Brazil', 'BR', 'country'::public.location_type, -14.235, -51.9253, 'Home to the largest share of the Amazon rainforest, with a largely hydropower-based electricity system and globally significant biodiversity.', false),
    ('Colombia', 'Colombia', 'CO', 'country'::public.location_type, 4.5709, -74.2973, 'One of the most biodiverse countries on Earth, spanning Andean páramos, Amazon rainforest and two ocean coastlines.', false),
    ('Mexico', 'Mexico', 'MX', 'country'::public.location_type, 23.6345, -102.5528, 'A megadiverse country facing water stress in its central and northern regions, air pollution in major cities and coastal hurricane exposure.', false),
    ('United States', 'United States', 'US', 'country'::public.location_type, 37.0902, -95.7129, 'A large and climatically diverse country exposed to hurricanes, wildfire, drought, heat and coastal flooding.', false),
    ('Canada', 'Canada', 'CA', 'country'::public.location_type, 56.1304, -106.3468, 'The world''s second-largest country by area, with vast boreal forests and Arctic territories that are warming faster than the global average.', false),
    ('Australia', 'Australia', 'AU', 'country'::public.location_type, -25.2744, 133.7751, 'A largely arid continent with highly variable rainfall, severe bushfire seasons and globally significant marine ecosystems.', false),
    ('United Kingdom', 'United Kingdom', 'GB', 'country'::public.location_type, 55.3781, -3.436, 'An island nation with a legally binding net zero target, managing flood risk, urban air quality and a rapidly decarbonising electricity grid.', false),
    ('Germany', 'Germany', 'DE', 'country'::public.location_type, 51.1657, 10.4515, 'Europe''s largest economy, pursuing its Energiewende energy transition while adapting to heat, drought and heavy rainfall events.', false),
    ('Netherlands', 'Netherlands', 'NL', 'country'::public.location_type, 52.1326, 5.2913, 'A delta nation where a large share of land lies below sea level, protected by one of the world''s most developed flood defence systems.', false),
    ('Denmark', 'Denmark', 'DK', 'country'::public.location_type, 56.2639, 9.5018, 'A low-lying Nordic country with a large share of wind power in its electricity supply and long-standing district heating networks.', false),
    ('France', 'France', 'FR', 'country'::public.location_type, 46.2276, 2.2137, 'A country with a low-carbon, largely nuclear electricity supply that is increasingly affected by heatwaves, drought and wildfire in the south.', false)
    ON CONFLICT (name, country) DO NOTHING;

    INSERT INTO public.issues (location_id, category_id, title, severity, summary, description)
    SELECT l.id, c.id, v.title, v.severity::public.severity_level, v.summary, v.description FROM (VALUES
    ('Lahore', 'Pakistan', 'air', 'Winter smog in Lahore', 'critical', 'Seasonal smog episodes sharply reduce air quality across the city each winter.', 'Between roughly October and February, cool stable air traps pollution close to the ground over the Punjab plain. Traffic, brick kilns, industry, domestic burning and regional crop residue burning all contribute. Fine particulate matter (PM2.5) is the pollutant of greatest health concern because it penetrates deep into the lungs and bloodstream. Concentrations during episodes are documented by monitoring networks and by the World Health Organization as far above health-based guideline levels.'),
    ('Lahore', 'Pakistan', 'nature', 'Urban tree cover and heat in Lahore', 'moderate', 'Expanding built-up area and loss of green space intensify urban heat and dust.', 'Rapid horizontal urban expansion has replaced vegetated land and agricultural plots with built surfaces. Tree canopy and open green space moderate surface temperature, retain dust and support infiltration of rainwater. Where canopy is lost, surfaces absorb and re-radiate more heat, and airborne dust is less readily captured. Restoring canopy is a recognised low-regret intervention, though its effect on regional particulate pollution is limited compared with controlling emission sources.'),
    ('Karachi', 'Pakistan', 'climate', 'Extreme heat in Karachi', 'high', 'Humid heat events in a coastal megacity create serious health risk, especially during power interruptions.', 'Karachi experiences high temperatures combined with coastal humidity, which limits the human body''s ability to cool by sweating. The 2015 heatwave caused widespread heat-related illness and deaths, documented by Pakistani authorities and in peer-reviewed public health literature. Risk is concentrated among outdoor workers, people without reliable electricity for fans or cooling, and residents of dense, poorly ventilated housing with little shade.'),
    ('Karachi', 'Pakistan', 'waste', 'Solid waste and drainage blockage in Karachi', 'high', 'Uncollected waste blocks stormwater channels and worsens urban flooding.', 'Collection coverage does not reach all neighbourhoods, and a significant share of municipal waste is dumped informally or burned. Plastic and mixed waste accumulate in natural and engineered drainage channels. During monsoon rainfall this reduces channel capacity and contributes to urban flooding. Open burning of waste also releases pollutants into local air.'),
    ('Jakarta', 'Indonesia', 'water', 'Land subsidence and flooding in Jakarta', 'critical', 'Parts of Jakarta are sinking, largely due to groundwater extraction, increasing flood exposure.', 'Jakarta sits on a low-lying alluvial delta crossed by many rivers. Extensive extraction of groundwater for domestic and commercial supply compacts underlying sediments, causing the land surface to sink. Subsidence has been measured in northern Jakarta by geodetic surveys and satellite radar. As the ground drops relative to the sea, tidal flooding, river flooding and drainage failure all become harder to manage. Indonesia''s response includes coastal defences, piped water expansion to reduce groundwater use, and the relocation of the national capital.'),
    ('Jakarta', 'Indonesia', 'air', 'Urban air pollution in Jakarta', 'high', 'Traffic, industry and power generation degrade air quality across the metropolitan area.', 'The Jakarta metropolitan region combines heavy road traffic, industrial activity and nearby fossil-fuelled power generation. Air quality monitoring regularly records fine particulate concentrations above World Health Organization guideline levels, with the worst conditions in the dry season. Indonesian courts and government agencies have both addressed the issue, and emission controls, vehicle standards and public transport expansion are central responses.'),
    ('Cape Town', 'South Africa', 'water', 'Drought and municipal water security in Cape Town', 'high', 'The 2015-2018 drought brought the city close to shutting off its municipal supply.', 'Cape Town depends on surface reservoirs filled by winter rainfall. Three consecutive poor rainfall years drew dam storage down to critical levels, and the city publicised a "Day Zero" at which municipal taps would largely be turned off. Severe restrictions, pressure management, leak repair and an extraordinary demand reduction by residents, together with returning rainfall, avoided that outcome. The episode is widely studied as a case of urban water crisis management, and the city has since diversified supply planning.'),
    ('Dubai', 'United Arab Emirates', 'energy', 'Cooling demand and the energy transition in Dubai', 'moderate', 'Extreme heat drives very high cooling loads, shaping the city''s energy system.', 'In a desert climate, air conditioning is essential and represents a large share of building electricity demand, peaking in summer. Historically this demand has been met largely with natural gas generation. The emirate is deploying large-scale solar capacity, which aligns well with daytime cooling peaks, alongside building efficiency codes and district cooling. Full decarbonisation also requires evening and night-time supply, which is where storage and demand management matter.'),
    ('Dubai', 'United Arab Emirates', 'water', 'Desalination dependence in Dubai', 'moderate', 'Almost all potable water comes from energy-intensive desalination of seawater.', 'The United Arab Emirates has very low natural renewable freshwater availability and relies on seawater desalination for most municipal supply. Desalination requires substantial energy and produces concentrated brine that is returned to the Gulf, a semi-enclosed and already saline sea. Efficiency improvements, a shift from thermal to membrane-based reverse osmosis, renewable-powered plants, treated wastewater reuse and demand management are the main levers.'),
    ('Miami', 'United States', 'oceans', 'Sea level rise and tidal flooding in Miami', 'critical', 'Rising seas cause recurrent sunny-day flooding and threaten freshwater supplies.', 'South Florida sits at low elevation on highly porous limestone, so seawater moves through the bedrock as well as over the surface. Tide gauge and satellite records document sea level rise along the southeastern United States coast. The practical consequences include high-tide flooding of streets and stormwater systems that cannot drain by gravity, saltwater intrusion into the Biscayne aquifer that supplies drinking water, and greater storm surge reach during hurricanes.'),
    ('Miami', 'United States', 'climate', 'Hurricane and storm surge exposure in Miami', 'high', 'Dense coastal development concentrates people and assets in the path of tropical cyclones.', 'Southeast Florida is one of the most hurricane-exposed metropolitan areas in the United States. Risk is a combination of hazard, exposure and vulnerability: decades of coastal development have placed very large populations and property values close to the shoreline, while rising sea level raises the baseline from which storm surge acts. Building codes, evacuation planning, wetland and dune restoration and insurance reform all form part of the response.'),
    ('Manaus / Amazon', 'Brazil', 'nature', 'Amazon deforestation and forest degradation', 'critical', 'Clearing and degradation reduce forest cover with global climate and biodiversity consequences.', 'The Brazilian Amazon is monitored continuously by Brazil''s National Institute for Space Research (INPE), whose PRODES and DETER systems publish annual and near-real-time deforestation data. Clearing is driven mainly by conversion to pasture and cropland, land speculation, road access and illegal logging and mining. Beyond outright clearing, fire and selective logging degrade forest that remains standing. Consequences include carbon emissions, biodiversity loss and disruption of the moisture recycling that sustains regional rainfall.'),
    ('Manaus / Amazon', 'Brazil', 'water', 'Extreme river drought in the Amazon basin', 'high', 'Severe low-water events disrupt river transport, supply and ecosystems.', 'Amazonian communities depend on rivers for transport, food and water. In recent severe droughts, river levels at Manaus and across the basin fell far enough to strand vessels, isolate communities, interrupt supply chains and cause fish and river dolphin mortality. Brazilian hydrological services publish river level records for Manaus that span more than a century, allowing individual events to be placed in historical context.'),
    ('Singapore', 'Singapore', 'water', 'Water security on a land-scarce island', 'moderate', 'A city-state with no natural freshwater reserves has engineered a diversified supply.', 'Singapore has a small land area, high population density and no natural aquifers or large rivers. Its national water agency describes supply as "four national taps": local catchment water, imported water, reclaimed water (NEWater) and desalinated water. Rainfall is abundant but storage is limited by land, so catchment, reclamation and desalination are combined with strong demand management and leak control. The approach is internationally cited, but reclamation and desalination are energy intensive.'),
    ('Singapore', 'Singapore', 'waste', 'Waste and landfill capacity in Singapore', 'high', 'With almost no land for landfill, waste is incinerated and the ash sent to a single offshore site.', 'Non-recycled waste is incinerated for energy recovery, and the resulting ash plus non-incinerable waste is deposited at Semakau Landfill, the country''s only remaining landfill site. Because land is finite, extending the landfill''s life depends directly on reducing waste generated and increasing material recovery. National policy has therefore focused on a circular economy approach, including packaging reporting and extended producer responsibility for electronics.'),
    ('Delhi', 'India', 'air', 'Delhi''s winter air pollution', 'critical', 'Meteorology, regional burning and local emissions produce extreme seasonal particulate pollution.', 'Each winter, cold stagnant air over the Indo-Gangetic Plain traps emissions near the surface. Transport, industry, construction dust, waste burning, domestic fuel use and post-monsoon crop residue burning in neighbouring states all contribute. The World Health Organization and Indian monitoring agencies document fine particulate concentrations far above health-based guidelines during these episodes. Responses include a graded emergency response plan, fuel and vehicle standards, and programmes to provide alternatives to crop residue burning.'),
    ('Delhi', 'India', 'water', 'Groundwater depletion in the Delhi region', 'high', 'Extraction exceeds recharge across much of the National Capital Territory.', 'India''s Central Ground Water Board assesses groundwater extraction against recharge across the country and has repeatedly classed large parts of Delhi as over-exploited. Urban expansion has sealed recharge surfaces, while piped supply gaps push households and businesses to rely on borewells. Falling water tables raise pumping energy costs, can worsen water quality, and reduce resilience during dry years.'),
    ('Rotterdam', 'Netherlands', 'climate', 'Living below sea level: Rotterdam''s delta defence', 'moderate', 'Most of the city lies below sea level and depends on continuous engineered protection.', 'Rotterdam sits in the Rhine-Meuse delta, with the majority of its area below sea level. Protection combines dikes, the Maeslant storm surge barrier, pumping and a national Delta Programme that plans decades ahead for sea level rise and changing river discharge. The city has also pioneered adaptation inside the flood defences, including water plazas, green roofs and water storage in public space to manage intense rainfall.'),
    ('Rotterdam', 'Netherlands', 'energy', 'Port decarbonisation in Rotterdam', 'high', 'Europe''s largest seaport is also a major industrial emissions cluster undergoing transition.', 'The port hosts refineries, chemical plants and bulk fossil fuel handling, making it one of the largest single concentrations of industrial carbon emissions in the European Union. The Port of Rotterdam Authority and Dutch government have published a transition strategy built around electrification, hydrogen import and production, carbon capture and storage in depleted offshore gas fields, and circular feedstocks. Progress is measurable but the transition is long-term and capital intensive.'),
    ('Northern Pakistan / Gilgit-Baltistan', 'Pakistan', 'climate', 'Glacier change and outburst floods in Gilgit-Baltistan', 'high', 'Warming is changing high-mountain glaciers and increasing the hazard from glacial lake outburst floods.', 'Gilgit-Baltistan holds thousands of glaciers that supply meltwater to the Indus river system. Across the wider Hindu Kush Himalaya, scientific assessments document widespread glacier mass loss as temperatures rise, although parts of the Karakoram have shown comparatively stable or anomalous glacier behaviour. As glaciers retreat, meltwater can pool behind unstable moraine or ice dams. A sudden failure — a glacial lake outburst flood (GLOF) — can send a destructive surge down narrow valleys where villages, roads, bridges and farmland are concentrated. Landslides and surging glaciers add further hazards, as the 2010 Attabad landslide, which dammed the Hunza River and created a lake, demonstrated.'),
    ('Mumbai', 'India', 'water', 'Monsoon flooding in Mumbai', 'high', 'Intense monsoon rainfall, high tides and constrained drainage cause recurrent flooding across the city.', 'Mumbai receives most of its annual rainfall during the southwest monsoon. When very heavy rain coincides with high tide, outfalls into the sea can be blocked, and water backs up through an ageing drainage network. Much of the city sits on land reclaimed from the sea and from the channels that once separated its islands, and natural drainage paths such as creeks, rivers and mangrove areas have been narrowed or built over. The extreme rainfall of 26 July 2005 caused catastrophic flooding and loss of life, and prompted major reviews of drainage and flood preparedness.'),
    ('Mumbai', 'India', 'nature', 'Mangrove loss and protection in Mumbai', 'moderate', 'Mangroves that buffer the coast and creeks have been reduced by reclamation, but are now legally protected.', 'Mangrove forests line Mumbai''s creeks, including Thane Creek, and provide flood buffering, nursery habitat for fish and roosting and feeding areas for birds, including migratory flamingos. Historic land reclamation and infrastructure development reduced mangrove extent. Court orders and state protection have since restricted clearing, and Maharashtra established a dedicated mangrove conservation unit. Pressures remain from infrastructure projects, dumping of debris and waste, and pollution from untreated sewage.'),
    ('Bengaluru', 'India', 'water', 'Lake loss and water stress in Bengaluru', 'high', 'A city far from major rivers depends on distant pumped water and depleted groundwater, while many of its historic lakes have been lost or polluted.', 'Bengaluru historically relied on a network of interconnected man-made lakes (tanks) that stored monsoon rainfall. Rapid urban growth has seen many lakes encroached on, disconnected or filled, while others receive untreated sewage — Bellandur Lake became widely known for toxic foam and fires. Municipal supply is pumped from the Cauvery River, far away and at a much lower elevation, and does not reach all parts of the city, so many households and businesses rely on borewells and private water tankers. A weak monsoon preceding 2024 led to acute shortages across parts of the city in early 2024.'),
    ('Beijing', 'China', 'air', 'Beijing''s air pollution control', 'moderate', 'Severe winter smog prompted sustained national and regional action, and fine particulate levels have fallen substantially since 2013.', 'In the early 2010s Beijing experienced extreme winter smog episodes driven by coal heating, industry, traffic and regional pollution across the North China Plain. China''s 2013 Air Pollution Prevention and Control Action Plan and subsequent measures targeted coal use, industrial emissions and vehicles across Beijing, Tianjin and Hebei. The UN Environment Programme''s 2019 review of two decades of air pollution control in Beijing documented significant reductions in fine particulate concentrations. Levels remain above the World Health Organization''s health-based guideline, and regional coordination remains essential.'),
    ('Beijing', 'China', 'water', 'Water scarcity on the North China Plain', 'high', 'Beijing sits in one of the world''s most water-stressed regions, with long-term groundwater decline and reliance on water transfers.', 'The North China Plain supports a very large population and intensive agriculture with limited renewable water. Decades of groundwater pumping caused water tables to fall and land to subside in parts of the region. To supplement supply, China built the South-to-North Water Diversion Project, whose central route began delivering water from the Danjiangkou Reservoir to Beijing in 2014. Groundwater management and water pricing reforms aim to reduce over-extraction.'),
    ('Shanghai', 'China', 'climate', 'Subsidence, storm surge and sea level rise in Shanghai', 'high', 'A low-lying delta megacity faces compounding risk from typhoons, storm surge, river floods and rising seas.', 'Shanghai lies on the flat alluvial plain of the Yangtze River delta, with much of the city only a few metres above sea level. Heavy groundwater extraction in the twentieth century caused significant land subsidence; the city has since restricted pumping and reinjected water into aquifers to slow sinking. Typhoons can combine storm surge, high astronomical tides and heavy rainfall, and the IPCC identifies large delta cities as particularly exposed to sea level rise. The city relies on extensive floodwalls along the Huangpu River and coastal seawalls, alongside a national ''sponge city'' programme to manage rainfall.'),
    ('Dhaka', 'Bangladesh', 'air', 'Air pollution in Dhaka', 'critical', 'Brick kilns, traffic, construction dust and regional pollution make dry-season air quality in Dhaka among the poorest of any major city.', 'Dhaka''s air quality deteriorates sharply during the dry season, roughly November to March, when brick kilns around the city operate and rainfall no longer washes particles from the air. The World Bank and Bangladesh''s Department of Environment identify brick kilns, vehicles, construction and road dust, and industrial emissions as major sources, with transboundary pollution across the Indo-Gangetic Plain also contributing. Fine particulate concentrations are documented far above WHO guideline levels.'),
    ('Dhaka', 'Bangladesh', 'water', 'River pollution and waterlogging in Dhaka', 'high', 'The rivers around Dhaka are heavily polluted, and monsoon rain regularly floods streets where canals and wetlands have been lost.', 'Dhaka is encircled by rivers including the Buriganga, Turag, Shitalakshya and Balu. Industrial effluent — historically from the Hazaribagh tannery district — together with untreated sewage and solid waste, has severely degraded water quality. Tanneries were relocated to an industrial estate at Savar from 2017, but pollution concerns there and in the rivers persist. Within the city, the loss of canals, ponds and low-lying wetlands to development reduces drainage, so heavy monsoon rain causes widespread waterlogging.'),
    ('Coastal Bangladesh / Khulna', 'Bangladesh', 'climate', 'Cyclones, storm surge and salinity in coastal Bangladesh', 'critical', 'The southwest coast faces repeated cyclones and creeping salinity that affect farming, drinking water and health.', 'The low-lying southwest of Bangladesh lies at the head of the Bay of Bengal, where tropical cyclones such as Sidr (2007), Aila (2009) and Amphan (2020) have brought destructive storm surges. Salinity in soil, rivers and groundwater has increased across much of the coastal zone, influenced by storm surges, reduced upstream freshwater flows in the dry season, shrimp aquaculture and sea level rise. Bangladesh has also become internationally recognised for reducing cyclone deaths dramatically through its early warning and shelter programme.'),
    ('Coastal Bangladesh / Khulna', 'Bangladesh', 'nature', 'Pressure on the Sundarbans mangrove forest', 'high', 'The world''s largest continuous mangrove forest faces salinity change, industrial pressure and extreme storms.', 'The Sundarbans, shared by Bangladesh and India, is the largest contiguous mangrove forest in the world and a UNESCO World Heritage Site. It is habitat for the Bengal tiger and many other species and shields inland communities from cyclones. Changes in freshwater flow and salinity, cyclone damage, shipping accidents including oil spills, and industrial development nearby have raised conservation concerns, which UNESCO''s World Heritage Committee has examined.'),
    ('Kalimantan / Indonesian Borneo', 'Indonesia', 'nature', 'Deforestation and peatland fires in Kalimantan', 'critical', 'Forest conversion and drained peatlands have made Kalimantan a hotspot for biodiversity loss and fire-driven emissions.', 'Kalimantan''s lowland rainforests and deep tropical peat swamps store large amounts of carbon and support species such as the critically endangered Bornean orangutan. Conversion to oil palm and pulpwood plantations, mining and logging has cleared large areas. Draining peatlands dries them out, and in dry years, especially El Niño years such as 2015 and 2019, peat fires have burned extensively, producing transboundary haze across Southeast Asia and large carbon emissions. Indonesia has since introduced a moratorium on new permits in primary forest and peatland and established a peatland restoration agency.'),
    ('Manila', 'Philippines', 'waste', 'Plastic pollution in Manila''s rivers and bay', 'high', 'Rivers flowing through Metro Manila carry large volumes of plastic waste into Manila Bay.', 'A 2021 study in Science Advances estimated that a large share of global riverine plastic emissions come from many small and medium urban rivers, and identified the Philippines — and rivers in Metro Manila, including the Pasig — as major contributors. Single-use sachets, widely used for small quantities of household goods, are hard to collect and recycle. Gaps in waste collection, especially in informal settlements along waterways, mean waste enters rivers and drainage channels, worsening flooding and marine pollution.'),
    ('Manila', 'Philippines', 'climate', 'Typhoons and flooding in Metro Manila', 'high', 'Metro Manila is regularly affected by typhoons and monsoon rains that cause severe flooding.', 'The Philippines lies in one of the most active tropical cyclone basins in the world. Metro Manila is built on low-lying land between Manila Bay and Laguna de Bay, and extreme rainfall events such as Tropical Storm Ketsana (Ondoy) in 2009 caused extensive flooding. Land subsidence in parts of the metropolitan area, linked to groundwater extraction, and waterway encroachment add to flood risk.'),
    ('Palawan', 'Philippines', 'oceans', 'Coral reefs and marine biodiversity in Palawan', 'moderate', 'Palawan''s reefs and mangroves are rich in biodiversity but face pressure from warming, destructive fishing and tourism.', 'Palawan lies at the edge of the Coral Triangle, the global centre of marine biodiversity. The Tubbataha Reefs Natural Park, a UNESCO World Heritage Site in the Sulu Sea, is a well-studied example of a well-protected, no-take reef. Elsewhere, reefs face pressure from marine heatwaves that cause coral bleaching, destructive fishing practices, sedimentation from land clearing and mining, and rapid tourism growth in destinations such as El Nido and Coron.'),
    ('Tokyo', 'Japan', 'climate', 'Urban heat in Tokyo', 'high', 'The combination of global warming and a strong urban heat island makes Tokyo''s summers increasingly dangerous.', 'The Japan Meteorological Agency documents a long-term rise in Tokyo''s mean temperature that is larger than the national average rise, reflecting both global warming and the urban heat island effect. Hot, humid summers bring increased emergency transport for heatstroke, especially among older people. The city has promoted heat countermeasures including cool pavements, green roofs and misting, and Japan''s national heatstroke alert system warns the public of dangerous conditions.'),
    ('Tokyo', 'Japan', 'water', 'River flood defence in Tokyo', 'moderate', 'Large parts of eastern Tokyo lie below high-water levels and depend on levees and massive underground infrastructure.', 'Eastern Tokyo''s lowlands between the Arakawa and Edogawa rivers include zero-metre areas lying at or below sea level, partly due to historical subsidence from groundwater pumping. Typhoons such as Hagibis in 2019 brought heavy rainfall that tested the region''s defences. Infrastructure such as the Metropolitan Area Outer Underground Discharge Channel in Saitama, with its vast underground tunnels and tanks, diverts floodwater from smaller rivers into the Edogawa.'),
    ('Singapore', 'Singapore', 'climate', 'Urban heat and greening in Singapore', 'moderate', 'A hot, humid city-state is warming, and uses urban greenery and planning to keep neighbourhoods cooler.', 'Singapore''s Meteorological Service documents a long-term warming trend, and the dense built environment intensifies heat through the urban heat island effect. The city has built its identity as a ''City in Nature'' with extensive parks, park connectors, skyrise greenery requirements and street trees. Research programmes such as Cooling Singapore study how building layout, materials and greenery affect outdoor thermal comfort, and the government has set out plans to expand nature parks and plant more trees.'),
    ('Dubai', 'United Arab Emirates', 'climate', 'Extreme heat in Dubai', 'high', 'Summer heat and humidity in the Gulf reach levels that are dangerous for outdoor work and daily life.', 'Dubai''s summers combine very high air temperatures with humidity from the warm waters of the Gulf. The IPCC identifies the region as one where extreme heat is projected to intensify further. Rapid urban growth, dark surfaces and waste heat from air conditioning add to local heat. The UAE applies a mandatory midday work break for outdoor labourers during the hottest summer months, and the city''s design increasingly emphasises shading, cooling and indoor connectivity.'),
    ('Nairobi', 'Kenya', 'waste', 'Waste management and the Dandora dumpsite in Nairobi', 'high', 'Much of Nairobi''s waste ends up at a large, long-overfilled open dumpsite in the east of the city.', 'The Dandora dumpsite has served as Nairobi''s main disposal site for decades and has long exceeded its intended capacity. Open burning, leachate and uncontrolled scavenging create health and environmental risks for surrounding communities, while informal waste pickers recover recyclable materials. Kenya introduced one of the world''s strictest bans on plastic carrier bags in 2017, and passed the Sustainable Waste Management Act in 2022 to move toward segregation, recycling and extended producer responsibility.'),
    ('Nairobi', 'Kenya', 'water', 'Nairobi River pollution', 'high', 'The Nairobi River and its tributaries carry sewage, industrial effluent and solid waste through the city.', 'The Nairobi River system flows through informal settlements and industrial areas where sanitation coverage is incomplete. Untreated sewage, industrial discharges and dumped waste have severely degraded water quality. Repeated restoration efforts, including a government-led regeneration programme, have focused on clearing waste, relocating structures from riparian land and building sewer infrastructure.'),
    ('Northern Kenya', 'Kenya', 'water', 'Recurring drought in northern Kenya', 'critical', 'Successive failed rainy seasons have caused severe livestock losses and food insecurity among pastoralist communities.', 'Northern Kenya''s arid and semi-arid counties, including Turkana, Marsabit and Mandera, depend on two short rainy seasons for pasture and water. Between late 2020 and early 2023, the Horn of Africa experienced five consecutive failed rainy seasons, described by the World Meteorological Organization and humanitarian agencies as the region''s worst drought in decades. Millions of livestock died and food insecurity rose sharply. Kenya''s National Drought Management Authority monitors conditions and coordinates early action.'),
    ('Northern Kenya', 'Kenya', 'nature', 'Lake Turkana under pressure', 'high', 'The world''s largest desert lake depends on inflow from Ethiopia''s Omo River, which has been altered by dams and irrigation.', 'Lake Turkana is fed mainly by the Omo River from Ethiopia. The construction of the Gibe III dam and associated irrigated agriculture in the lower Omo valley changed the river''s flow regime. UNESCO''s World Heritage Committee added the Lake Turkana National Parks to the List of World Heritage in Danger in 2018, citing the potential effects of upstream development on the lake''s water levels and ecosystem, which support fisheries and pastoralist communities.'),
    ('Lagos', 'Nigeria', 'water', 'Flooding and coastal erosion in Lagos', 'high', 'A low-lying lagoon city faces recurrent rainfall flooding, coastal erosion and rising seas.', 'Lagos is built around a lagoon system on a low, sandy coastline. Heavy rainfall during the wet season regularly floods streets, particularly where drains are blocked by waste or wetlands have been filled. The Atlantic shoreline has experienced significant erosion, and large coastal projects, including the Eko Atlantic development built on reclaimed land with a protective sea wall, have become part of the debate about how to manage the coast. The IPCC identifies West African coastal cities as highly exposed to sea level rise.'),
    ('Lagos', 'Nigeria', 'waste', 'Solid waste in Lagos', 'high', 'Waste volumes in one of Africa''s largest cities strain collection systems and dumpsites.', 'Lagos generates very large volumes of solid waste. Much is taken to dumpsites such as Olusosun, one of the largest in Africa, which experienced a major fire in 2018. Waste that is not collected often ends up in drains, canals and the lagoon, worsening flooding and pollution. The state has worked with private sector participation operators and informal collectors, and has piloted recycling and materials recovery initiatives.'),
    ('Niger Delta', 'Nigeria', 'nature', 'Oil pollution in the Niger Delta', 'critical', 'Decades of oil spills have contaminated land, creeks and groundwater in one of the world''s great wetlands.', 'The Niger Delta holds extensive mangroves and freshwater swamp forests and supports fishing and farming communities. Since oil production began in the 1950s, spills from operational failures, ageing pipelines, sabotage and illegal refining have contaminated soil, water and mangroves. The UN Environment Programme''s 2011 Environmental Assessment of Ogoniland found widespread and severe contamination, including drinking water contaminated with hydrocarbons, and recommended a clean-up that could take decades. Nigeria established the Hydrocarbon Pollution Remediation Project (HYPREP) to implement the recommendations.'),
    ('Niger Delta', 'Nigeria', 'energy', 'Gas flaring in the Niger Delta', 'high', 'Associated gas burned off at oil facilities wastes energy and releases pollutants and greenhouse gases.', 'When crude oil is extracted, natural gas often comes up with it. Where infrastructure to use or capture it is lacking, this associated gas is burned in flares. Nigeria has been among the countries with the highest flaring volumes, according to the World Bank''s Global Gas Flaring Tracker. Flaring releases carbon dioxide, black carbon and other pollutants, and communities near flare sites report noise, heat and health concerns. Nigeria has committed to reducing routine flaring and launched a programme to commercialise flare gas.'),
    ('Madagascar', 'Madagascar', 'nature', 'Forest loss and endemic species in Madagascar', 'critical', 'Madagascar''s unique wildlife depends on forests that have been extensively cleared.', 'Madagascar split from other landmasses tens of millions of years ago, and a very high proportion of its plants and animals occur nowhere else — including all of the world''s wild lemurs. Forest clearance for shifting agriculture (tavy), charcoal and fuelwood production, logging and mining has removed much of the island''s original forest cover. The IUCN Red List assesses the large majority of lemur species as threatened. The Rainforests of the Atsinanana World Heritage Site has been on the List of World Heritage in Danger since 2010, following illegal logging of rosewood and other precious timber.'),
    ('Madagascar', 'Madagascar', 'water', 'Drought and food insecurity in southern Madagascar', 'critical', 'Repeated drought in the Grand Sud has caused severe food insecurity.', 'Southern Madagascar is semi-arid and prone to drought. Consecutive poor rainy seasons around 2019–2021 led to severe food insecurity, with the World Food Programme and partners scaling up emergency assistance. A World Weather Attribution study found that rainfall variability was the main driver and that the role of human-induced climate change in that drought was small, highlighting underlying vulnerability — poverty, limited infrastructure and land degradation — as key factors in the crisis.'),
    ('Bogotá', 'Colombia', 'water', 'Páramo ecosystems and Bogotá''s water supply', 'moderate', 'Most of Bogotá''s drinking water originates in high-Andean páramo ecosystems that are sensitive to land use and climate change.', 'Páramos are high-altitude Andean grasslands and wetlands whose mosses, soils and plants such as frailejones store and slowly release water. Bogotá draws much of its supply from páramo areas including Chingaza. Colombia has delimited páramos and restricted mining and agriculture within them by law, but they remain vulnerable to cattle grazing, potato farming, fire and warming temperatures. A drought linked to El Niño led Bogotá to introduce water rationing in 2024.'),
    ('Bogotá', 'Colombia', 'air', 'Air quality and transport in Bogotá', 'moderate', 'Diesel vehicles and industry affect air quality, while bus rapid transit and cycling policy offer internationally studied responses.', 'Bogotá''s air quality is affected by diesel buses and trucks, industry and resuspended dust, with pollution often worse in the southwest of the city. Bogotá is known for TransMilenio, a large bus rapid transit system opened in 2000, its Ciclovía — weekly car-free streets — and an extensive cycle network. The city has been adding electric buses to its fleet, which has become one of the largest electric bus fleets outside China.'),
    ('Colombian Amazon', 'Colombia', 'nature', 'Deforestation in the Colombian Amazon', 'critical', 'Forest clearing concentrated in an arc of deforestation threatens connectivity between the Andes and the Amazon.', 'Colombia''s official forest monitoring by IDEAM identifies the Amazon region as the country''s main deforestation hotspot, concentrated in departments such as Caquetá, Guaviare and Meta. Land grabbing, conversion to cattle pasture, illicit crops and road building are major drivers. The shifting security situation following the 2016 peace agreement changed control over remote forest areas. Chiribiquete National Park, a UNESCO World Heritage Site, has been expanded and is a focus for protection. Colombia has reported declines in deforestation in some recent years, though trends vary.'),
    ('Mexico City', 'Mexico', 'water', 'Subsidence and water stress in Mexico City', 'critical', 'Pumping from the aquifer beneath a former lake bed causes some of the fastest urban subsidence in the world, while supply remains unreliable.', 'Mexico City was built on the bed of Lake Texcoco. Heavy extraction from the underlying aquifer, which supplies a large share of the city''s water, has caused the soft clay to compact, and parts of the city are sinking rapidly, as documented by satellite radar studies. Subsidence damages pipes, buildings and drainage, increasing leaks and flooding. The city also imports water from the Cutzamala System, whose reservoirs fell to very low levels during recent droughts, leading to supply restrictions.'),
    ('Mexico City', 'Mexico', 'air', 'Ozone pollution in Mexico City', 'high', 'A high-altitude basin traps pollution, and ozone episodes still trigger emergency restrictions.', 'Mexico City sits in a high basin surrounded by mountains, where intense sunlight and weak ventilation favour ozone formation from vehicle and industrial emissions. Once considered one of the most polluted cities in the world, it made significant progress from the 1990s through fuel reformulation, catalytic converters and driving restrictions (Hoy No Circula). Ozone remains a persistent problem, and the metropolitan environmental commission activates environmental contingency phases during severe episodes.'),
    ('Los Angeles', 'United States', 'climate', 'Wildfire risk in Los Angeles', 'critical', 'Dry vegetation, strong winds and homes built into fire-prone landscapes create severe wildfire risk.', 'Southern California''s Mediterranean climate and native chaparral vegetation are naturally fire-prone. Santa Ana winds in autumn and winter can drive fires rapidly into communities at the wildland–urban interface. In January 2025, the Palisades and Eaton fires destroyed thousands of structures in the Los Angeles area. The IPCC describes how warming increases the dryness of fuels and lengthens fire seasons in the western United States.'),
    ('Los Angeles', 'United States', 'air', 'Smog in the Los Angeles basin', 'high', 'Decades of regulation have greatly improved air quality, but the region still records some of the highest ozone levels in the United States.', 'Los Angeles gave its name to photochemical smog. Since the mid-twentieth century, California''s regulations — from vehicle emission standards to the creation of the California Air Resources Board — have significantly reduced pollution. The South Coast Air Basin still frequently exceeds federal ozone standards because of its geography, sunshine and large emissions from vehicles, ports and goods movement.'),
    ('Phoenix', 'United States', 'climate', 'Extreme heat in Phoenix', 'critical', 'Phoenix experiences some of the most dangerous heat of any large US city, with heat-related deaths tracked closely by the county.', 'Phoenix sits in the Sonoran Desert, and its summers are long and extremely hot. In July 2023, the city recorded an unprecedented run of consecutive days at or above 110°F (43.3°C), according to the National Weather Service. Maricopa County''s public health department publishes annual heat death reports, which have documented rising heat-related deaths, with people experiencing homelessness disproportionately affected. The city created a dedicated Office of Heat Response and Mitigation in 2021.'),
    ('Phoenix', 'United States', 'water', 'Colorado River supply and groundwater in Phoenix', 'high', 'Long-term drought on the Colorado River has led to cuts in Arizona''s allocation, increasing focus on groundwater and conservation.', 'The Phoenix area draws water from the Colorado River via the Central Arizona Project, from the Salt and Verde rivers, and from groundwater. A multi-decade drought and overallocation on the Colorado River lowered Lake Mead, leading the US Bureau of Reclamation to declare shortage conditions and reduce Arizona''s allocation. Arizona''s 1980 Groundwater Management Act requires new developments in active management areas to demonstrate an assured water supply.'),
    ('Western Canada', 'Canada', 'climate', 'Wildfire and heat in Western Canada', 'critical', 'Record-breaking heat and wildfire seasons have affected communities, forests and air quality across British Columbia and Alberta.', 'In late June 2021, a heat dome brought unprecedented temperatures to British Columbia; the village of Lytton set a Canadian national temperature record and was destroyed by fire the next day. The BC Coroners Service reported hundreds of heat-related deaths. Canada''s 2023 wildfire season was the most extensive on record nationally, forcing large evacuations, including in British Columbia and Alberta, and sending smoke across North America. Earlier, the 2016 Fort McMurray fire forced the evacuation of the entire city.'),
    ('Arctic Canada', 'Canada', 'climate', 'Permafrost thaw in Arctic Canada', 'high', 'Warming is thawing permanently frozen ground, damaging infrastructure and changing northern landscapes and ways of life.', 'Canada''s Changing Climate Report (2019) found that northern Canada has warmed at about three times the global rate. Permafrost — ground that stays frozen for at least two consecutive years — underlies much of the territories. As it thaws, the ground can slump, damaging buildings, roads, airstrips and pipelines, and releasing carbon. Changes in sea ice, snow and weather also affect Inuit hunting, travel and food security.'),
    ('Great Barrier Reef', 'Australia', 'oceans', 'Marine heatwaves and coral bleaching on the Great Barrier Reef', 'critical', 'Repeated mass bleaching events driven by ocean warming are the greatest threat to the reef.', 'When sea temperatures stay unusually high, corals expel the symbiotic algae that provide much of their energy and colour, and turn white. Prolonged or severe bleaching kills corals. The Great Barrier Reef Marine Park Authority has documented mass bleaching events in 2016, 2017, 2020, 2022 and 2024, with the shortening gap between events leaving less time for recovery. The Authority''s 2024 Outlook Report identifies climate change as the greatest threat to the reef''s long-term outlook. NOAA''s Coral Reef Watch monitors heat stress globally.'),
    ('Great Barrier Reef', 'Australia', 'nature', 'Water quality and crown-of-thorns starfish on the Great Barrier Reef', 'high', 'Runoff from farmland and outbreaks of coral-eating starfish add to the pressure from warming.', 'Sediment, nutrients and pesticides from agricultural catchments flow onto inshore reefs, reducing light and promoting algae. Nutrient runoff is also linked to outbreaks of crown-of-thorns starfish, which eat coral and have caused significant coral loss. Governments have invested in improving farm practices and in a starfish control programme that culls outbreaks on high-value reefs.'),
    ('Sydney', 'Australia', 'climate', 'Bushfire smoke and heat in Sydney', 'high', 'The 2019–20 Black Summer fires blanketed Sydney in smoke, and Western Sydney faces much hotter conditions than the coast.', 'During Australia''s 2019–20 ''Black Summer'', bushfires burned vast areas of south-eastern Australia and smoke repeatedly pushed Sydney''s air quality to hazardous levels. Research published afterwards estimated a substantial health burden from the smoke. Heat is also a growing concern: Western Sydney, further from the cooling sea breeze and with less tree canopy, experiences considerably hotter summer days than the eastern suburbs, and the Bureau of Meteorology has recorded extreme temperatures at Penrith.'),
    ('London', 'United Kingdom', 'air', 'Traffic pollution and the Ultra Low Emission Zone in London', 'moderate', 'Nitrogen dioxide from traffic has been a long-standing problem, and London''s low-emission zones have been extensively studied.', 'After the Great Smog of 1952, the UK passed the Clean Air Act 1956, which reduced coal smoke. Modern pollution in London is dominated by road traffic, particularly diesel vehicles emitting nitrogen dioxide and particulates. London introduced the Ultra Low Emission Zone in central London in 2019, expanded it in 2021 and extended it London-wide in 2023. City Hall has reported large reductions in roadside nitrogen dioxide since the scheme began, although fine particulate levels remain above WHO guideline values.'),
    ('London', 'United Kingdom', 'water', 'Tidal flood risk on the Thames', 'moderate', 'London is protected from North Sea surges by the Thames Barrier and a long-term adaptation plan.', 'London''s tidal Thames is exposed to storm surges from the North Sea, as the deadly 1953 North Sea flood showed. The Thames Barrier, operational since 1982, can close to protect the city. The Environment Agency''s Thames Estuary 2100 plan sets out how flood defences will be maintained, raised and eventually replaced as sea levels rise, using an adaptive pathways approach that can respond to how quickly sea levels actually rise.'),
    ('Berlin', 'Germany', 'climate', 'Heat, drought and Berlin''s sponge city approach', 'moderate', 'Hotter, drier summers and heavy downpours are prompting Berlin to keep rainwater in the city.', 'Berlin has experienced several hot and dry summers in recent years, stressing street trees, urban forests and groundwater, while intense summer storms can overwhelm sewers. The city''s rainwater management rules require new developments to manage rainwater on site where possible — through green roofs, infiltration and retention — rather than sending it to the sewer, an approach often described as the ''Schwammstadt'' or sponge city. Berlin''s Senate Department publishes an urban climate atlas mapping heat exposure across the city.'),
    ('Berlin', 'Germany', 'energy', 'Decarbonising heat in Berlin', 'moderate', 'Heating buildings is a large share of Berlin''s emissions, and the city is shifting district heating away from coal.', 'Much of Berlin''s building stock is heated by gas, oil or a large district heating network historically supplied by coal and gas power plants. The state of Berlin has legislated a coal phase-out for its heating plants and set a climate neutrality target. Germany''s national energy transition (Energiewende) and building energy law shape the move toward heat pumps, renewable heat and more efficient buildings.'),
    ('Southern France', 'France', 'climate', 'Heatwaves, drought and wildfire in southern France', 'high', 'Mediterranean France is facing hotter summers, drier soils and a widening wildfire season.', 'On 28 June 2019, Météo-France recorded France''s highest temperature on record, 46.0°C, at Vérargues in Hérault. The 2003 heatwave caused a very large number of excess deaths in France and prompted a national heatwave plan. In 2022, a severe drought affected much of the country, and large wildfires burned in the Gironde and elsewhere. The IPCC identifies the Mediterranean as a region where warming and drying trends increase fire weather and water stress.'),
    ('Arctic', 'International', 'climate', 'Arctic amplification and sea ice loss', 'critical', 'The Arctic is warming much faster than the global average, and summer sea ice has declined markedly since satellite records began.', 'A 2022 study in Communications Earth & Environment found that the Arctic has warmed nearly four times faster than the globe since 1979. Satellite records maintained by the US National Snow and Ice Data Center show a long-term decline in Arctic sea ice extent, especially at the September minimum. Loss of reflective ice and snow allows more solar energy to be absorbed, a feedback that amplifies warming. The Greenland ice sheet is losing mass and contributing to global sea level rise.'),
    ('Copenhagen', 'Denmark', 'climate', 'Cloudburst flooding and Copenhagen''s adaptation plan', 'moderate', 'A severe 2011 cloudburst led Copenhagen to redesign streets, parks and squares to handle extreme rain.', 'On 2 July 2011, an extreme cloudburst flooded large parts of Copenhagen, causing extensive damage to basements, roads and infrastructure. In response, the city adopted a Cloudburst Management Plan in 2012, which combines conventional sewer upgrades with surface solutions: streets designed to channel water, parks that can temporarily store it, and green areas that absorb rainfall. Projects such as the climate-adapted Enghaveparken and Tåsinge Plads have become internationally referenced examples.'),
    ('Copenhagen', 'Denmark', 'energy', 'Decarbonising Copenhagen', 'low', 'District heating, wind power and cycling form the core of Copenhagen''s climate strategy.', 'Copenhagen set a goal of becoming carbon neutral by 2025 in its CPH 2025 Climate Plan, and has publicly reported difficulty meeting that goal in full. Nearly all buildings are connected to district heating, which has been shifted from coal toward biomass and waste heat. The city is known for its cycling infrastructure, and the Amager Bakke waste-to-energy plant combines heat and power generation with a public ski slope. Denmark''s large share of wind power supports the decarbonisation of electricity.')
    ) AS v(loc, country, cat, title, severity, summary, description)
    JOIN public.locations l ON l.name = v.loc AND l.country = v.country
    JOIN public.categories c ON c.slug = v.cat
    ON CONFLICT (title) DO NOTHING;

    INSERT INTO public.causes (issue_id, title, description)
    SELECT i.id, v.title, v.description FROM (VALUES
    ('Winter smog in Lahore', 'Temperature inversion', 'Cool, stable winter air forms a lid over the Punjab plain, preventing pollutants from dispersing upward.'),
    ('Winter smog in Lahore', 'Road transport', 'A large, ageing vehicle fleet with varying fuel and engine standards emits particulates and precursor gases.'),
    ('Winter smog in Lahore', 'Brick kilns and industry', 'Traditional kilns and industrial combustion in and around the city release particulates, especially where cleaner technologies have not been adopted.'),
    ('Winter smog in Lahore', 'Regional crop residue burning', 'Post-harvest burning across the wider Punjab region, on both sides of the border, adds smoke that travels into the airshed.'),
    ('Winter smog in Lahore', 'Domestic and waste burning', 'Burning of solid fuel for heating and open burning of waste add localised particulate emissions.'),
    ('Urban tree cover and heat in Lahore', 'Horizontal urban expansion', 'Low-density growth converts vegetated and agricultural land into built surfaces.'),
    ('Urban tree cover and heat in Lahore', 'Road widening and construction', 'Infrastructure projects frequently remove mature roadside trees, whose cooling benefit takes decades to replace.'),
    ('Extreme heat in Karachi', 'Humid coastal climate', 'High humidity limits evaporative cooling, so the body struggles to shed heat even at moderate air temperatures.'),
    ('Extreme heat in Karachi', 'Urban heat island', 'Dense construction, dark surfaces and limited vegetation keep built-up areas warmer than surroundings, especially at night.'),
    ('Extreme heat in Karachi', 'Unreliable electricity supply', 'Power interruptions during peak demand remove access to fans and cooling exactly when risk is highest.'),
    ('Solid waste and drainage blockage in Karachi', 'Incomplete collection coverage', 'Formal collection does not reach every neighbourhood, leaving waste to accumulate or be dumped informally.'),
    ('Solid waste and drainage blockage in Karachi', 'Plastic in drainage channels', 'Lightweight plastic waste migrates into stormwater drains and natural channels, reducing their capacity.'),
    ('Solid waste and drainage blockage in Karachi', 'Encroachment on natural drains', 'Construction on and alongside natural watercourses narrows the space available for flood flow.'),
    ('Land subsidence and flooding in Jakarta', 'Groundwater extraction', 'Pumping from shallow and deep aquifers compacts sediments and lowers the land surface.'),
    ('Land subsidence and flooding in Jakarta', 'Incomplete piped water coverage', 'Where piped supply is unavailable or unreliable, households and businesses drill their own wells.'),
    ('Land subsidence and flooding in Jakarta', 'Delta geology and building loads', 'Soft young alluvial sediments compact naturally and further under the weight of dense construction.'),
    ('Land subsidence and flooding in Jakarta', 'Upstream land use and river sedimentation', 'Changes in the catchment increase runoff and sediment, reducing channel capacity downstream.'),
    ('Urban air pollution in Jakarta', 'Road traffic', 'Large numbers of cars and motorcycles in a congested metropolitan area produce sustained emissions.'),
    ('Urban air pollution in Jakarta', 'Industry and power generation', 'Industrial facilities and fossil-fuelled power plants in the surrounding region contribute to the regional pollutant load.'),
    ('Urban air pollution in Jakarta', 'Dry-season meteorology', 'Reduced rainfall and weaker dispersion in the dry season allow pollutants to accumulate.'),
    ('Drought and municipal water security in Cape Town', 'Consecutive low-rainfall years', 'Three successive poor winter rainfall seasons reduced inflow to the supply dams.'),
    ('Drought and municipal water security in Cape Town', 'Surface-water dependence', 'A supply system built almost entirely on rainfall-fed reservoirs is highly sensitive to rainfall variability.'),
    ('Drought and municipal water security in Cape Town', 'Demand growth and distribution losses', 'Population growth and losses from ageing pipe networks raised baseline demand before the drought.'),
    ('Cooling demand and the energy transition in Dubai', 'Extreme summer temperatures', 'Sustained high temperatures make mechanical cooling a necessity rather than a comfort choice.'),
    ('Cooling demand and the energy transition in Dubai', 'Building stock and glazing', 'Highly glazed towers gain heat rapidly unless shading, insulation and efficient systems are specified.'),
    ('Cooling demand and the energy transition in Dubai', 'Gas-based generation legacy', 'Electricity has historically been supplied largely by natural gas, tying cooling demand to fossil fuel use.'),
    ('Desalination dependence in Dubai', 'Very low natural freshwater availability', 'Rainfall is minimal and there are no significant perennial rivers or renewable aquifers.'),
    ('Desalination dependence in Dubai', 'High per-capita demand', 'Landscaping, tourism and high living standards raise water use per person.'),
    ('Desalination dependence in Dubai', 'Brine discharge to a semi-enclosed sea', 'Concentrated brine returned to the Gulf raises local salinity and temperature near outfalls.'),
    ('Sea level rise and tidal flooding in Miami', 'Global sea level rise', 'Thermal expansion of seawater and melting land ice raise mean sea level, documented by tide gauges and satellite altimetry.'),
